using System;
using System.Collections.Generic;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[Serializable]
public class ActionFace
{
	[HideInInspector]
	public string FaceName;

	public int ActionValue;

	[SerializeField]
	[HideInInspector]
	private int m_actionValueModifier;

	[HideInInspector]
	private bool m_isModifierLocked;

	private List<ActionValueModifier> actionValueModifiers = new List<ActionValueModifier>();

	public BattleAction BattleAction;

	public bool EnableSecondAction;

	[ShowIf("EnableSecondAction")]
	[AllowNesting]
	public int SecondActionValue;

	[SerializeField]
	[HideInInspector]
	private int m_secondActionValueModifier;

	[HideInInspector]
	private bool m_isSecondModifierLocked;

	private List<ActionValueModifier> secondActionValueModifiers = new List<ActionValueModifier>();

	[ShowIf("EnableSecondAction")]
	[AllowNesting]
	public BattleAction SecondBattleAction;

	[HideInInspector]
	public bool KeepChanges;

	[HideInInspector]
	public bool KeepChangesForBattle;

	[HideInInspector]
	public BattleAction NewBattleAction;

	[HideInInspector]
	public int NewActionValue;

	[HideInInspector]
	public BattleAction NewSecondBattleAction;

	[HideInInspector]
	public int NewSecondActionValue;

	public int ActionValueModifier
	{
		get
		{
			return m_actionValueModifier;
		}
		set
		{
			if (!m_isModifierLocked)
			{
				m_actionValueModifier = value;
			}
		}
	}

	public int ModifiedActionValue => ActionValue + ActionValueModifier;

	[HideInInspector]
	public int SecondActionValueModifier
	{
		get
		{
			return m_secondActionValueModifier;
		}
		set
		{
			if (!m_isSecondModifierLocked)
			{
				m_secondActionValueModifier = value;
			}
		}
	}

	public int SecondModifiedActionValue => SecondActionValue + SecondActionValueModifier;

	private List<ActionValueModifier> GetActionValueModifiers(ref List<ActionValueModifier> actionValueModifiersRef)
	{
		if (actionValueModifiersRef == null)
		{
			actionValueModifiersRef = new List<ActionValueModifier>();
		}
		return actionValueModifiersRef;
	}

	public ActionFace()
	{
	}

	public ActionFace(string FaceName, int ActionValue, BattleAction BattleAction)
	{
		this.FaceName = FaceName;
		this.ActionValue = ActionValue;
		if (BattleAction != null)
		{
			this.BattleAction = BattleAction;
		}
	}

	public ActionFace(string FaceName, int ActionValue, BattleAction BattleAction, int SecondActionValue, BattleAction SecondBattleAction)
	{
		this.FaceName = FaceName;
		this.ActionValue = ActionValue;
		if (BattleAction != null)
		{
			this.BattleAction = BattleAction;
		}
		EnableSecondAction = true;
		this.SecondActionValue = SecondActionValue;
		if (SecondBattleAction != null)
		{
			this.SecondBattleAction = SecondBattleAction;
		}
	}

	public void ToggleActionValueModifier(List<ActionValueModifier> actionValueModifiersExternal)
	{
		for (int i = 0; i < actionValueModifiersExternal.Count; i++)
		{
			ToggleActionValueModifierFirstAction(actionValueModifiersExternal);
			ToggleActionValueModifierSecondAction(actionValueModifiersExternal);
		}
	}

	private void ToggleActionValueModifierFirstAction(List<ActionValueModifier> actionValueModifiersExternal)
	{
		for (int i = 0; i < actionValueModifiersExternal.Count; i++)
		{
			ActionValueModifier actionValueModifier = actionValueModifiersExternal[i];
			ToggleActionValueModifier(actionValueModifier.ActionValueModifierAmount, actionValueModifier.BattleActionInteractionEnum, ref BattleAction, ref actionValueModifiers, firstAction: true);
		}
	}

	private void ToggleActionValueModifierSecondAction(List<ActionValueModifier> actionValueModifiersExternal)
	{
		for (int i = 0; i < actionValueModifiersExternal.Count; i++)
		{
			if (EnableSecondAction)
			{
				ActionValueModifier actionValueModifier = actionValueModifiersExternal[i];
				ToggleActionValueModifier(actionValueModifier.ActionValueModifierAmount, actionValueModifier.BattleActionInteractionEnum, ref SecondBattleAction, ref secondActionValueModifiers, firstAction: false);
			}
		}
	}

	private void ToggleActionValueModifier(int actionValueModifierAmount, BattleActionInteractionEnum battleActionInteractionEnum, ref BattleAction battleAction, ref List<ActionValueModifier> actionValueModifiersRef, bool firstAction)
	{
		GetActionValueModifiers(ref actionValueModifiersRef);
		int actionValueModifierAmount2 = (battleAction.BaseBattleActionData.HasBattleActionInteractionEnum(battleActionInteractionEnum) ? actionValueModifierAmount : 0);
		ToggleActionValueModifier(actionValueModifierAmount2, battleActionInteractionEnum, ref actionValueModifiersRef, firstAction);
	}

	private void ToggleActionValueModifier(int actionValueModifierAmount, BattleActionInteractionEnum battleActionInteractionEnum, ref List<ActionValueModifier> actionValueModifiersRef, bool firstAction)
	{
		bool flag = false;
		for (int i = 0; i < actionValueModifiersRef.Count; i++)
		{
			if (actionValueModifiersRef[i].BattleActionInteractionEnum == battleActionInteractionEnum)
			{
				flag = true;
				actionValueModifiersRef[i].ActionValueModifierAmount = actionValueModifierAmount;
			}
		}
		if (!flag)
		{
			actionValueModifiersRef.Add(new ActionValueModifier(actionValueModifierAmount, battleActionInteractionEnum));
		}
		if (firstAction)
		{
			UpdateActionValueModifierTotalSingleAction(ref actionValueModifiers, delegate(int value)
			{
				ActionValueModifier = value;
			});
		}
		else
		{
			UpdateActionValueModifierTotalSingleAction(ref secondActionValueModifiers, delegate(int value)
			{
				SecondActionValueModifier = value;
			});
		}
	}

	private void UpdateActionValueModifierTotalSingleAction(ref List<ActionValueModifier> actionValueModifiersRef, Action<int> actionValueModifierSetterAction)
	{
		GetActionValueModifiers(ref actionValueModifiersRef);
		int num = 0;
		for (int i = 0; i < actionValueModifiersRef.Count; i++)
		{
			num += actionValueModifiersRef[i].ActionValueModifierAmount;
		}
		actionValueModifierSetterAction(num);
	}

	public void UpdateActionValueModifier()
	{
		ToggleActionValueModifierFirstAction(GetActionValueModifiers(ref actionValueModifiers));
		ToggleActionValueModifierSecondAction(GetActionValueModifiers(ref secondActionValueModifiers));
	}

	public void RemoveActionValueModifier(BattleActionInteractionEnum battleActionInteractionEnum)
	{
		ToggleActionValueModifier(0, battleActionInteractionEnum, ref BattleAction, ref actionValueModifiers, firstAction: true);
		if (EnableSecondAction)
		{
			ToggleActionValueModifier(0, battleActionInteractionEnum, ref SecondBattleAction, ref secondActionValueModifiers, firstAction: false);
		}
	}

	public void ResetActionValueModifiers()
	{
		UnlockActionModifiers();
		ActionValueModifier = 0;
		GetActionValueModifiers(ref actionValueModifiers).Clear();
		SecondActionValueModifier = 0;
		GetActionValueModifiers(ref secondActionValueModifiers).Clear();
	}

	public string ValueText(int value)
	{
		if (value == EffectsValues.NO_VALUE || value == -1)
		{
			return " ";
		}
		return value.ToString();
	}

	public void TurnActionValueIntoModifiedActionValueAndReset()
	{
		ActionValue = ModifiedActionValue;
		ActionValueModifier = 0;
		GetActionValueModifiers(ref actionValueModifiers).Clear();
	}

	public void TurnSecondActionValueIntoModifiedActionValueAndReset()
	{
		SecondActionValue = SecondModifiedActionValue;
		SecondActionValueModifier = 0;
		GetActionValueModifiers(ref secondActionValueModifiers).Clear();
	}

	public void SetActionModifierLock(bool isLocked)
	{
		m_isModifierLocked = isLocked;
	}

	public void SetSecondActionModifierLock(bool isLocked)
	{
		m_isSecondModifierLocked = isLocked;
	}

	public void UnlockActionModifiers()
	{
		SetActionModifierLock(isLocked: false);
		SetSecondActionModifierLock(isLocked: false);
	}
}
